 if resp.clicked(){if let Some(pos)=resp.interact_pointer_pos(){*time=((pos.x-left)/width*span).clamp(0.,span);}}
 for (i,k) in o.motion.keys.iter_mut().enumerate().take(1024){if !k.time.is_finite()||k.time<0.||k.time>span{continue;}let point=egui::pos2(x(k.time),r.top()+36.+(i%3) as f32*22.);let hit=egui::Rect::from_center_size(point,egui::vec2(16.,16.));let drag=ui.interact(hit,id.with(i),egui::Sense::click_and_drag());if drag.clicked()||drag.dragged(){selected=Some(i);if drag.dragged(){k.time=(k.time+ui.input(|v|v.pointer.delta().x)/width*span).clamp(0.,span);}*time=k.time;}p.add(egui::Shape::convex_polygon(vec![point+egui::vec2(0.,-6.),point+egui::vec2(6.,0.),point+egui::vec2(0.,6.),point+egui::vec2(-6.,0.)],if selected==Some(i){egui::Color32::GOLD}else{egui::Color32::LIGHT_BLUE},egui::Stroke::NONE));}
