pub(super) fn geometry_and_metadata(ui:&mut egui::Ui,o:&mut Object,root:&std::path::Path,time:f32,status:&mut String){ui.collapsing("Frame geometry & atlas metadata",|ui|{
 let frame=o.animation.frame(time);let mut geom=o.animation.frame_geometry.get(&frame).copied().unwrap_or([0.,0.,1.,1.]);let mut changed=false;
 if !forge_engine::valid_region(geom){geom=[0.,0.,1.,1.];}
 ui.horizontal_wrapped(|ui|{for (label,v) in ["X ","Y ","W ","H "].into_iter().zip(geom.iter_mut()){changed|=ui.add(egui::DragValue::new(v).range(0. ..=1.).speed(0.005).prefix(label)).changed();}});
 let (canvas,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().clamp(80.,220.),160.),egui::Sense::hover());let side=canvas.width().min(canvas.height())-12.;let r=egui::Rect::from_center_size(canvas.center(),egui::vec2(side,side));let p=ui.painter_at(canvas);p.rect_filled(r,3.,ui.visuals().extreme_bg_color);
 let draw=if forge_engine::valid_region(geom){geom}else{[0.,0.,1.,1.]};let a=r.min+egui::vec2(draw[0]*side,draw[1]*side);let b=a+egui::vec2(draw[2]*side,draw[3]*side);let region=egui::Rect::from_min_max(a,b);p.rect_filled(region,0.,egui::Color32::from_rgba_unmultiplied(80,150,210,65));for y in [a.y,b.y]{p.line_segment([egui::pos2(a.x,y),egui::pos2(b.x,y)],egui::Stroke::new(1.5,egui::Color32::LIGHT_BLUE));}for x in [a.x,b.x]{p.line_segment([egui::pos2(x,a.y),egui::pos2(x,b.y)],egui::Stroke::new(1.5,egui::Color32::LIGHT_BLUE));}
 let handle=egui::Rect::from_center_size(b,egui::vec2(12.,12.));p.rect_filled(handle,2.,egui::Color32::LIGHT_BLUE);let id=ui.id().with(("geom27",o.id,frame));let drag=ui.interact(region.shrink(4_f32.min(region.width()*0.25).min(region.height()*0.25)),id.with("move"),egui::Sense::drag());let resize=ui.interact(handle,id.with("resize"),egui::Sense::drag());let delta=ui.input(|i|i.pointer.delta())/side;
 if resize.dragged(){geom[2]=(geom[2]+delta.x).clamp(0.001,(1.-geom[0]).max(0.001));geom[3]=(geom[3]+delta.y).clamp(0.001,(1.-geom[1]).max(0.001));changed=true;}else if drag.dragged(){geom[0]=(geom[0]+delta.x).clamp(0.,(1.-geom[2]).max(0.));geom[1]=(geom[1]+delta.y).clamp(0.,(1.-geom[3]).max(0.));changed=true;}
 if changed{if forge_engine::valid_region(geom){o.animation.frame_geometry.insert(frame,geom);}else{*status="Geometry must fit within normalized original frame".into();}}
 if ui.button("Reset frame geometry").clicked(){o.animation.frame_geometry.remove(&frame);}ui.small("Geometry is normalized against the original logical frame; collider is unchanged.");
 if ui.button("Store clip + sync atlas metadata").clicked(){match forge_engine::sync_atlas_metadata(root,o){Ok(path)=>{o.clips.insert(o.clip_name.clone(),o.animation.clone());*status=format!("Metadata: {path}");},Err(err)=>*status=err}}
 });}

