 let clip=o.clip_name.clone();let id=ui.id().with(("scalar27",o.id,clip.as_str()));let mut axis=ui.ctx().data(|d|d.get_temp::<usize>(id)).unwrap_or(0).min(5);let mut span=ui.ctx().data(|d|d.get_temp::<f32>(id.with("span"))).unwrap_or(2.).clamp(0.1,3600.);let mut range=ui.ctx().data(|d|d.get_temp::<f32>(id.with("range"))).unwrap_or(180.).clamp(1.,100000.);ui.horizontal_wrapped(|ui|{for(i,name)in ["X","Y","Rotation","Scale X","Scale Y","Opacity"].iter().enumerate(){ui.selectable_value(&mut axis,i,*name);}});ui.horizontal(|ui|{ui.add(egui::DragValue::new(&mut span).range(0.1..=3600.).suffix(" s"));ui.add(egui::DragValue::new(&mut range).range(1. ..=100000.).prefix("±"));});
