 let visual=axis>=3;let exists=if visual{o.motion.visual_channels.contains_key(&clip)}else{o.motion.property_channels.contains_key(&clip)};if visual&&!exists&&o.motion.visual_channels.len()<128&&ui.button("Enable visual channels").clicked(){o.motion.visual_channels.insert(clip.clone(),Default::default());range=2.;}if ui.add_enabled(!visual&&!exists&&o.motion.property_channels.len()<128&&(o.motion.clip_keys.contains_key(&clip)||o.motion.clip_keys.len()<128),egui::Button::new("Enable property channels")).clicked(){let base=forge_engine::Key{time:0.,position:o.position,rotation:o.rotation,smooth:false,bezier:None};let fallback=o.motion.keys.iter().take(1024).cloned().collect::<Vec<_>>();let track=o.motion.clip_keys.entry(clip.clone()).or_insert(fallback);if track.is_empty(){track.push(base);}o.motion.property_channels.insert(clip.clone(),Default::default());}if exists&&ui.button("Remove property channels").clicked(){if visual{o.motion.visual_channels.remove(&clip);}else{o.motion.property_channels.remove(&clip);}}
 let base_value=match axis{0|1=>o.position[axis],2=>o.rotation,_=>1.};let track=if visual{o.motion.visual_channels.get_mut(&clip)}else{o.motion.property_channels.get_mut(&clip)};if let Some(ch)=track{let keys=&mut ch[axis%3];let shift_id=id.with((axis,"shift29"));let mut shift=ui.ctx().data(|d|d.get_temp::<f32>(shift_id)).unwrap_or(0.1);ui.horizontal_wrapped(|ui|{ui.add(egui::DragValue::new(&mut shift).range(-3600. ..=3600.).speed(0.01).suffix(" s"));if ui.add_enabled(!keys.is_empty(),egui::Button::new("Shift entire channel")).clicked(){let lo=keys.iter().map(|k|k.time).fold(f32::INFINITY,f32::min);let hi=keys.iter().map(|k|k.time).fold(f32::NEG_INFINITY,f32::max);let delta=shift.clamp(-lo,3600.-hi);for k in keys.iter_mut(){k.time+=delta;}}});ui.ctx().data_mut(|d|d.insert_temp(shift_id,shift));let mut selected=ui.ctx().data(|d|d.get_temp::<usize>(id.with((axis,"selected")))).filter(|i|*i<keys.len());let group_id=id.with((axis,"group30"));let clipboard=egui::Id::new(("scalar_clipboard30",axis));let mut group=ui.ctx().data(|d|d.get_temp::<Vec<usize>>(group_id)).unwrap_or_default();group.retain(|i|*i<keys.len());ui.horizontal_wrapped(|ui|{if ui.button("Select all keys").clicked(){group=(0..keys.len()).collect();}if ui.button("Clear group").clicked(){group.clear();}if ui.add_enabled(!group.is_empty(),egui::Button::new("Copy group")).clicked(){let copied:Vec<_>=group.iter().filter_map(|&i|keys.get(i).cloned()).collect();ui.ctx().data_mut(|d|d.insert_temp(clipboard,copied));}if ui.button("Paste at playhead").clicked(){if let Some(copied)=ui.ctx().data(|d|d.get_temp::<Vec<forge_engine::ScalarKey>>(clipboard)){match forge_engine::paste_scalar_group(keys,&copied,*time){Ok(indices)=>{selected=indices.first().copied();group=indices;ui.ctx().data_mut(|d|d.remove::<String>(group_id.with("error")));},Err(err)=>{ui.ctx().data_mut(|d|d.insert_temp(group_id.with("error"),err));}}}}if ui.add_enabled(!group.is_empty(),egui::Button::new("Delete group")).clicked(){group.sort_unstable();group.dedup();for i in group.drain(..).rev(){keys.remove(i);}selected=None;}if ui.add_enabled(!group.is_empty(),egui::Button::new("Group smooth")).clicked(){for &i in &group{keys[i].smooth=true;keys[i].bezier=None;keys[i].bezier_x=None;}}if ui.add_enabled(!group.is_empty(),egui::Button::new("Group Bezier")).clicked(){for &i in &group{keys[i].bezier=Some([0.15,0.85]);keys[i].bezier_x=None;}}});if let Some(err)=ui.ctx().data(|d|d.get_temp::<String>(group_id.with("error"))){ui.colored_label(egui::Color32::LIGHT_RED,err);}ui.small(format!("{} selected · Ctrl+click to toggle",group.len()));ui.horizontal(|ui|{if ui.add_enabled(keys.len()<1024,egui::Button::new("+ Key")).clicked(){let value=base_value;keys.push(forge_engine::ScalarKey{time:(*time).clamp(0.,span),value,smooth:false,bezier:None,bezier_x:None});selected=Some(keys.len()-1);}if ui.add_enabled(selected.is_some(),egui::Button::new("Delete key")).clicked(){if let Some(i)=selected.take(){keys.remove(i);group.clear();}}});
 let box_id=id.with((axis,"box31"));let mut box_mode=ui.ctx().data(|d|d.get_temp::<bool>(box_id)).unwrap_or(false);ui.checkbox(&mut box_mode,"Rectangle selection");ui.ctx().data_mut(|d|d.insert_temp(box_id,box_mode));let (r,box_response)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(100.),150.),if box_mode{egui::Sense::drag()}else{egui::Sense::hover()});let p=ui.painter_at(r);p.rect_filled(r,4.,ui.visuals().extreme_bg_color);let pos=|t:f32,v:f32|egui::pos2(r.left()+t/span*r.width(),r.center().y-v/range*r.height()*0.45);p.line_segment([egui::pos2(r.left(),r.center().y),egui::pos2(r.right(),r.center().y)],egui::Stroke::new(1.,ui.visuals().widgets.inactive.bg_stroke.color));let points:Vec<_>=(0..=96).filter_map(|i|{let t=span*i as f32/96.;forge_engine::sample_scalar(keys,t).map(|v|pos(t,v))}).collect();if points.len()>1{p.add(egui::Shape::line(points,egui::Stroke::new(1.5,egui::Color32::LIGHT_BLUE)));}let marquee_id=box_id.with("start");if box_mode{if box_response.drag_started(){if let Some(point)=box_response.interact_pointer_pos(){ui.ctx().data_mut(|d|d.insert_temp(marquee_id,point));}}if let Some(start)=ui.ctx().data(|d|d.get_temp::<egui::Pos2>(marquee_id)){if let Some(end)=ui.ctx().input(|i|i.pointer.latest_pos()){let rect=egui::Rect::from_two_pos(start,end).intersect(r);p.rect_filled(rect,0.,egui::Color32::from_rgba_unmultiplied(90,160,230,40));p.line_segment([rect.left_top(),rect.right_top()],egui::Stroke::new(1.,egui::Color32::LIGHT_BLUE));p.line_segment([rect.left_bottom(),rect.right_bottom()],egui::Stroke::new(1.,egui::Color32::LIGHT_BLUE));if box_response.drag_stopped(){group=keys.iter().enumerate().filter(|(_,k)|rect.contains(pos(k.time,k.value))).map(|(i,_)|i).collect();selected=group.first().copied();}}if box_response.drag_stopped()||!ui.input(|i|i.pointer.primary_down()){ui.ctx().data_mut(|d|d.remove::<egui::Pos2>(marquee_id));}}}let mut group_delta=None;for (i,k) in keys.iter_mut().enumerate(){let point=pos(k.time,k.value);if !r.contains(point){continue;}let response=ui.interact(egui::Rect::from_center_size(point,egui::vec2(14.,14.)),id.with((axis,i)),if box_mode{egui::Sense::hover()}else{egui::Sense::click_and_drag()});if response.clicked(){selected=Some(i);if ui.input(|v|v.modifiers.ctrl){if group.contains(&i){group.retain(|&j|j!=i);}else{group.push(i);}}else{group=vec![i];}}if response.clicked()||response.dragged(){selected=Some(i);if response.dragged(){let delta=ui.input(|v|v.pointer.delta());if group.len()>1&&group.contains(&i){group_delta=Some(delta.x/r.width()*span);}else{k.time=(k.time+delta.x/r.width()*span).clamp(0.,span);let v=k.value-delta.y/(r.height()*0.45)*range;k.value=if visual{v.clamp(if axis==5{0.}else{0.01},if axis==5{1.}else{16.})}else{v.clamp(-range,range)};}}*time=k.time;}p.circle_filled(pos(k.time,k.value),5.,if selected==Some(i)||group.contains(&i){egui::Color32::GOLD}else{egui::Color32::LIGHT_BLUE});}if let Some(delta)=group_delta{if forge_engine::move_scalar_group(keys,&group,delta,span){if let Some(i)=selected{*time=keys[i].time;}}}if let Some(i)=selected{if let Some(k)=keys.get(i){let t0=k.time;let v0=k.value;if let Some(next)=keys.iter().filter(|n|n.time>t0).min_by(|a,b|a.time.total_cmp(&b.time)){let t1=next.time;let v1=next.value;if let Some(mut controls)=k.bezier{let mut xs=k.bezier_x.unwrap_or([1./3.,2./3.]);let mut handles_changed=false;for j in 0..2{let t=t0+(t1-t0)*xs[j];let v=v0+(v1-v0)*controls[j];let point=pos(t,v);let anchor=pos(if j==0{t0}else{t1},if j==0{v0}else{v1});p.line_segment([anchor,point],egui::Stroke::new(1.,egui::Color32::GOLD));let response=ui.interact(egui::Rect::from_center_size(point,egui::vec2(12.,12.)),id.with((axis,i,j,"bezier29")),if box_mode{egui::Sense::hover()}else{egui::Sense::drag()});if response.dragged(){handles_changed=true;let delta=ui.input(|v|v.pointer.delta());xs[j]=(xs[j]+delta.x/r.width()*span/(t1-t0)).clamp(0.,1.);if (v1-v0).abs()>0.0001{controls[j]=(controls[j]-delta.y*range/(r.height()*0.45)/(v1-v0)).clamp(0.,1.);}}p.circle_filled(point,4.,egui::Color32::GOLD);}if handles_changed{keys[i].bezier=Some(controls);keys[i].bezier_x=Some(xs);}}}}}if let Some(k)=selected.and_then(|i|keys.get_mut(i)){ui.horizontal(|ui|{ui.add(egui::DragValue::new(&mut k.time).range(0. ..=3600.).suffix(" s"));if visual{ui.add(egui::DragValue::new(&mut k.value).range(if axis==5{0. ..=1.}else{0.01..=16.}));}else{ui.add(egui::DragValue::new(&mut k.value));}ui.checkbox(&mut k.smooth,"Smooth");let mut bezier=k.bezier.is_some();if ui.checkbox(&mut bezier,"Bezier").changed(){k.bezier=bezier.then_some([0.15,0.85]);k.bezier_x=None;}let bx=&mut k.bezier_x;if let Some(b)=&mut k.bezier{ui.menu_button("Curve presets",|ui|{for (name,values) in [("Linear",[1./3.,2./3.]),("Ease in",[0.,0.]),("Ease out",[1.,1.]),("Ease in-out",[0.,1.])]{if ui.button(name).clicked(){*b=values;*bx=None;}}});for v in b{ui.add(egui::DragValue::new(v).range(0. ..=1.).speed(0.01));}}});}ui.ctx().data_mut(|d|{d.insert_temp(group_id,group);if let Some(i)=selected{d.insert_temp(id.with((axis,"selected")),i);}else{d.remove::<usize>(id.with((axis,"selected")));}});ui.small("Empty axes use the base transform track. Drag key points to edit time and value; the vertical range is fixed while dragging.");}
